    // so we can check it beforehand.
    if (requestStream != null) {
      if (connectTimeoutTimer != null) {
        xhr.upload.onProgress.listen((event) {
          connectTimeoutTimer?.cancel();
          connectTimeoutTimer = null;
        });
      }

